// Implementation of two_sum that satisfies the Verus specification.
//
// We simply scan all pairs (i, j) with 0 ≤ i < j < nums.len() in
// lexicographic order, returning the first pair whose sum (via
// checked_add) equals target.  If no such pair exists, we return None.

fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    // Iterate i from 0 up to len−1
    for i in 0..nums.len() {
        // For each i, iterate j from i+1 up to len−1
        for j in (i + 1)..nums.len() {
            // Use checked_add to avoid overflow
            if nums[i].checked_add(nums[j]) == Some(target) {
                // This is the lexicographically first (i, j) that works
                return Some((i, j));
            }
        }
    }
    // No pair sums to the target
    None
}